CREATE TABLE IF NOT EXISTS __migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS currency (id TEXT PRIMARY KEY, name TEXT NOT NULL, rate NUMERIC(18,4) NOT NULL);
CREATE TABLE IF NOT EXISTS "user" (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS favorite_currency (user_id UUID REFERENCES "user"(id) ON DELETE CASCADE, currency_id TEXT REFERENCES currency(id) ON DELETE CASCADE, PRIMARY KEY (user_id, currency_id));
